INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('about-fostering','main','hero','{"lead": "PROVIDING HOPE, STABILITY & CARE", "heading": "About Fostering", "intro": "<p>At Safe Harbours, we believe that every child deserves a safe and nurturing environment. We offer children dealing with trauma, mental health challenges, or simply in need of somewhere to rest their head for the night, the opportunity to grow in supportive homes.</p>", "bg": "image-set(url(''/assets/uploads/2024/10/shutterstock_1575539629-2-1-1917.avif'') type(''image/avif''), url(''/assets/uploads/2024/10/shutterstock_1575539629-2-1-1917.webp'') type(''image/webp''), url(''/assets/uploads/2024/10/shutterstock_1575539629-2-1.jpg''))"}',0,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('about-fostering','main','banner','{"heading": "What is Foster Care?", "body": "<p>Foster care provides temporary homes for children who cannot stay with their birth families due to various circumstances including neglect, abuse, or family instability. As a foster parent, you’ll offer stability, love, and care to help these children. Safe Harbours specializes in placing children with nuanced needs, ensuring they receive the best care possible while fostering.</p><p><a href=\"/become-a-foster-parent/\">Get Started</a></p>", "shorten": false}',1,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('about-fostering','main','valueCards','{"heading": "Trauma-Based Care at Safe Harbours", "cards": [{"img": {"avif": "/assets/uploads/2024/10/heart-dark-icon-e1729696124837-123.avif 123w", "webp": "/assets/uploads/2024/10/heart-dark-icon-e1729696124837-123.webp 123w", "jpg": "/assets/uploads/2024/10/heart-dark-icon.png", "w": 123, "h": 125}, "title": "Understanding Trauma", "text": "<p>Many children in foster care have experienced significant trauma. At Safe Harbours, we focus on trauma-informed care, recognizing the emotional and psychological scars children may carry and providing the support they need to heal.</p>", "style": "lightpink"}, {"img": {"avif": "/assets/uploads/2024/10/hands-light-icon-146.avif 146w", "webp": "/assets/uploads/2024/10/hands-light-icon-146.webp 146w", "jpg": "/assets/uploads/2024/10/hands-light-icon.png", "w": 146, "h": 136}, "title": "Building Trust", "text": "<p>Foster children often struggle with trust due to their past experiences. We equip our foster parents with the tools and training to help children feel safe and supported, allowing them to rebuild trust at their own pace.</p>", "style": "darknavy"}, {"img": {"avif": "/assets/uploads/2024/10/heart-people-icon-158.avif 158w", "webp": "/assets/uploads/2024/10/heart-people-icon-158.webp 158w", "jpg": "/assets/uploads/2024/10/heart-people-icon.png", "w": 158, "h": 136}, "title": "Supporting Emotional Growth", "text": "<p>Children impacted by trauma require patience and understanding to overcome emotional challenges. Our training ensures foster parents can guide children through emotional regulation and help them process their experiences and feel safe.</p>", "style": "darknavy"}, {"img": {"avif": "/assets/uploads/2024/10/famly-icon-146.avif 146w", "webp": "/assets/uploads/2024/10/famly-icon-146.webp 146w", "jpg": "/assets/uploads/2024/10/famly-icon.png", "w": 146, "h": 136}, "title": "Collaborative Care", "text": "<p>Fostering is a team effort. At Safe Harbours, we work alongside foster parents, mental health professionals, and social workers to provide comprehensive, ongoing support tailored to each child’s needs.</p>", "style": "lightpink"}], "bg": "image-set(url(''/assets/uploads/2024/10/shutterstock_1575539629-1-1-1913.avif'') type(''image/avif''), url(''/assets/uploads/2024/10/shutterstock_1575539629-1-1-1913.webp'') type(''image/webp''), url(''/assets/uploads/2024/10/shutterstock_1575539629-1-1.jpg''))", "alt": false, "large": true, "cols": 2}',2,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('about-fostering','main','faqs','{"heading": "Frequently Asked Questions", "items": [{"q": "What impact will fostering have on my family?", "a": "<p>Accepting children into your home is a big decision and will have both positive and negative impacts. Your children will be sharing your time with someone new and each new child will bring their own unique needs. We''ve found that many foster families look back on their experiences with a sense of fulfillment and pride in helping others.</p>"}, {"q": "Do we have a choice on which child is placed in our home?", "a": "<p>Yes. The final decision to accept a child is yours. Nobody can force you to accept a placement referral.</p>"}, {"q": "What kind of information will I have to make a decision on accepting a child?", "a": "<p>Child welfare organizations do their best to provide a fulsome picture of the child''s strengths and needs. A document called a \"Pre-Placement Assessment\" will be provided to aid in your informed decision making. That said, sometimes children come into care on an emergency basis and these placements will need to be carefully considered.</p>"}, {"q": "Should I buy or rent a larger home to foster?", "a": "<p>Not at first. It''s best to use your existing home and only move if you feel ready to accept more children. Even then, you will need to ensure that a move would not add any financial hardship to your family.</p>"}, {"q": "I''m single - can I be a foster parent?", "a": "<p>Absolutely. Some consideration will be given to your time availability and work commitments as we do with all potential foster homes so just be sure you are able to handle this on your own. We will be happy to discuss your individual circumstances with you.</p>"}, {"q": "What sort of compensation do foster parents receive?", "a": "<p>Foster parents are not \"compensated\" the way an employee would. In fact, the money foster parents receive is meant to cover the costs of caring for an additional child. Some people get confused and see fostering as a job when it is more akin to being a volunteer. Depending on the needs of the child, a new foster parent will receive between $80 - $90 per day*(called a per diem) for each child placed in their home.<br>\n*Includes $5 training and compliance bonus plus $10 towards \"respite care\".</p>"}, {"q": "If I need a break, how does that work?", "a": "<p>Short-term breaks of a few days are called \"respite\". This can be done by a child staying at another foster home for a weekend or a youth worker staying at your home while you take some time for yourself. We will be happy to discuss the details of how this works with you.</p>"}, {"q": "My family goes to on vacation every year, can I bring the foster child?", "a": "<p>This will depend on if the child has court-ordered visits with their family and if their guardian is willing to approve the trip. Most of the time it isn''t a concern but if it is, we will work our best to provide a respite home for the child. In some cases, we even receive additional funding for airfare.</p>"}, {"q": "If my child has complex needs will I need to pay for services?", "a": "<p>No. While the \"per diem\" covers day-to-day costs such as clothing, hygiene, school supplies, etc., exceptional costs like dental, medical devices, therapy and more will have additional funding provided.</p>"}, {"q": "What does the application process look like?", "a": "<p>First, we discuss our program with you over the phone and ask some screening questions. If Safe Harbours and you want to move ahead, we will arrange a time to visit you and your family at your home. A visual assessment of your home and we discuss in more detail what to expect from caring for children living away from their home. Afterward, we send some paperwork for you to complete, we conduct interviews with everyone in the home for a report called a \"Home Study\", training is provided, and once all of that is complete - your home is open for placements.</p>"}, {"q": "What kind of caregiver screening takes place to keep kids safe?", "a": "<p>All caregivers need to complete a Vulnerable Sector Police Check and a Child Welfare Check. The child welfare check will let us know if the caregiver has even been involved in a child welfare investigation. Additionally, we contact references from the caregiver''s family and community.</p>"}, {"q": "If a placement isn''t working out or I decide fostering isn''t for me?", "a": "<p>This does happen and don''t feel bad if it does. Absent of a safety concern, we would notify the organization that referred the child to let them know they will need to seek out a new home. This can happen quickly or take a bit more time, up to 30 days. If it is your desire to stop fostering, we ask that you allow all children to move into their new homes before closing yours to new placements.</p>"}]}',3,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('about-fostering','main','cta','{"heading": "Ready To Get Started?", "body": "<p><strong>Are you ready to make a difference?</strong> Safe Harbours is here to guide you every step of the way. Contact us today to learn more about fostering and how you can get involved. <strong>Your journey to becoming a foster parent begins here…</strong></p>", "label": "Get Started", "href": "/become-a-foster-parent/"}',4,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('about-fostering','main','logos','{"heading": "Referral Partners", "logos": [{"img": {"avif": "/assets/uploads/2024/11/Group-34247-640.avif 640w", "webp": "/assets/uploads/2024/11/Group-34247-640.webp 640w", "jpg": "/assets/uploads/2024/11/Group-34247.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34246-640.avif 640w", "webp": "/assets/uploads/2024/11/Group-34246-640.webp 640w", "jpg": "/assets/uploads/2024/11/Group-34246.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34245-399.avif 399w", "webp": "/assets/uploads/2024/11/Group-34245-399.webp 399w", "jpg": "/assets/uploads/2024/11/Group-34245.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34244-537.avif 537w", "webp": "/assets/uploads/2024/11/Group-34244-537.webp 537w", "jpg": "/assets/uploads/2024/11/Group-34244.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34243-576.avif 576w", "webp": "/assets/uploads/2024/11/Group-34243-576.webp 576w", "jpg": "/assets/uploads/2024/11/Group-34243.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34237-522.avif 522w", "webp": "/assets/uploads/2024/11/Group-34237-522.webp 522w", "jpg": "/assets/uploads/2024/11/Group-34237.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34236-640.avif 640w, /assets/uploads/2024/11/Group-34236-1024.avif 1024w", "webp": "/assets/uploads/2024/11/Group-34236-640.webp 640w, /assets/uploads/2024/11/Group-34236-1024.webp 1024w", "jpg": "/assets/uploads/2024/11/Group-34236.png"}}]}',5,'published','');
